draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + (30 + 10*Math.sin(t))*Math.cos(3*t), H/2 + (30 + 10*Math.sin(t))*Math.sin(3*t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + (30 + 10*Math.sin(t))*Math.cos(5*t), H/2 + (30 + 10*Math.sin(t))*Math.sin(5*t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + (30 + 10*Math.sin(t))*Math.cos(7*t), H/2 + (30 + 10*Math.sin(t))*Math.sin(7*t));
  ctx.stroke();
  ctx.restore();
}
